CREATE TABLE public.buildings (
    id bigint NOT NULL,
    venue_id bigint NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    center_lat double precision,
    center_lng double precision,
    outline jsonb,
    sort_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT buildings_code_check CHECK ((btrim(code) <> ''::text))
);


